SELECT DATE(payment_date) AS date, AVG(amount) AS average_daily_revenue
FROM payment
GROUP BY DATE(payment_date);

SELECT COUNT(*) 
FROM customer 
WHERE email LIKE '%gmail%';

SELECT COUNT(*) 
FROM customer 
WHERE customer_id NOT IN (SELECT DISTINCT customer_id FROM rental);

SELECT COUNT(DISTINCT rental.customer_id) AS weekend_rentals
FROM rental
WHERE EXTRACT(DOW FROM rental.rental_date) IN (0, 6);

SELECT COUNT(*) 
FROM rental 
WHERE return_date IS NULL;

SELECT COUNT(*) 
FROM film 
WHERE rental_duration >= 7;

SELECT COUNT(*) 
FROM film 
WHERE title ILIKE '%LOVE%';

SELECT COUNT(*) 
FROM film 
WHERE length >= 120;

SELECT COUNT(DISTINCT city) 
FROM store 
WHERE address_id IN (SELECT address_id FROM address WHERE city IN (SELECT city FROM address WHERE country_id = (SELECT country_id FROM country WHERE country = 'United States')));

SELECT COUNT(*) 
FROM store 
WHERE store_id NOT IN (SELECT DISTINCT store_id FROM inventory WHERE inventory_id IN (SELECT inventory_id FROM rental));

SELECT COUNT(*) 
FROM film 
WHERE rental_rate = 0.99;

SELECT COUNT(*) 
FROM film 
WHERE rental_rate > 2.99;

SELECT COUNT(*) 
FROM film 
WHERE replacement_cost >= 20;

SELECT COUNT(*) 
FROM film 
WHERE rental_rate > (SELECT AVG(rental_rate) FROM film);

SELECT COUNT(*) 
FROM film 
WHERE special_features LIKE '%Deleted Scenes%';

SELECT COUNT(*) 
FROM inventory 
WHERE inventory.film_id IN (SELECT film.id FROM film WHERE film.id IS NOT NULL);

SELECT COUNT(*) 
FROM film 
WHERE length > (SELECT AVG(length) FROM film);
